import React, { useState } from 'react';
import { Link, useLocation } from 'react-router-dom';

const Navbar: React.FC = () => {
  const [isOpen, setIsOpen] = useState(false);
  const location = useLocation();

  const navLinks = [
    { name: 'Home', path: '/' },
    { name: 'About', path: '/about' },
    { name: 'Projects', path: '/projects' },
    { name: 'Quote & Booking', path: '/booking' },
  ];

  const isActive = (path: string) => location.pathname === path;

  return (
    <nav className="bg-white shadow-md sticky top-0 z-50">
      <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
        <div className="flex justify-between h-20">
          <div className="flex items-center">
            <Link to="/" className="flex-shrink-0 flex items-center">
              <span className="text-2xl font-bold tracking-tighter text-gray-900 oswald">
                HART <span className="text-[#CB4154]">STONE</span> LTD
              </span>
            </Link>
          </div>

          <div className="hidden md:flex items-center space-x-8">
            {navLinks.map((link) => (
              <Link
                key={link.path}
                to={link.path}
                className={`text-sm font-semibold tracking-wide uppercase transition-colors duration-200 ${
                  isActive(link.path) 
                    ? 'text-[#CB4154] border-b-2 border-[#CB4154]' 
                    : 'text-gray-600 hover:text-[#CB4154]'
                }`}
              >
                {link.name}
              </Link>
            ))}
          </div>

          <div className="md:hidden flex items-center">
            <button
              onClick={() => setIsOpen(!isOpen)}
              className="inline-flex items-center justify-center p-2 rounded-md text-gray-400 hover:text-gray-500 hover:bg-gray-100 focus:outline-none"
            >
              <svg className="h-6 w-6" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                {isOpen ? (
                  <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M6 18L18 6M6 6l12 12" />
                ) : (
                  <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M4 6h16M4 12h16M4 18h16" />
                )}
              </svg>
            </button>
          </div>
        </div>
      </div>

      {/* Mobile menu */}
      {isOpen && (
        <div className="md:hidden bg-white border-t border-gray-100 animate-in slide-in-from-top duration-300">
          <div className="px-2 pt-2 pb-3 space-y-1 sm:px-3">
            {navLinks.map((link) => (
              <Link
                key={link.path}
                to={link.path}
                onClick={() => setIsOpen(false)}
                className={`block px-3 py-2 rounded-md text-base font-medium ${
                  isActive(link.path) 
                    ? 'text-[#CB4154] bg-red-50' 
                    : 'text-gray-600 hover:text-[#CB4154] hover:bg-gray-50'
                }`}
              >
                {link.name}
              </Link>
            ))}
          </div>
        </div>
      )}
    </nav>
  );
};

export default Navbar;

import React, { useState, useEffect } from 'react';
import { BRICK_RATES, CONTACT_INFO } from '../constants';
import { ServiceType } from '../types';

const Booking: React.FC = () => {
  const [serviceType, setServiceType] = useState<ServiceType>(ServiceType.BRICK);
  const [area, setArea] = useState<number>(0);
  const [complexity, setComplexity] = useState<number>(1.0);
  const [includeMaterials, setIncludeMaterials] = useState<boolean>(true);

  const [estimate, setEstimate] = useState({
    labor: 0,
    materials: 0,
    subtotal: 0,
    gst: 0,
    total: 0
  });

  const [formState, setFormState] = useState({
    name: '',
    email: '',
    phone: '',
    notes: '',
    submitted: false
  });

  useEffect(() => {
    const laborRate = BRICK_RATES.labor[serviceType];
    const materialRate = BRICK_RATES.materials[serviceType];

    const totalLabor = (laborRate * area) * complexity;
    const totalMaterials = includeMaterials ? (materialRate * area) : 0;
    const subtotal = totalLabor + totalMaterials;
    const gst = subtotal * BRICK_RATES.taxRate;
    const total = subtotal + gst;

    setEstimate({
      labor: totalLabor,
      materials: totalMaterials,
      subtotal: subtotal,
      gst: gst,
      total: total
    });
  }, [serviceType, area, complexity, includeMaterials]);

  const formatCurrency = (val: number) => {
    return new Intl.NumberFormat('en-NZ', { style: 'currency', currency: 'NZD' }).format(val);
  };

  const handleFormSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    setFormState(prev => ({ ...prev, submitted: true }));
    // Simulate API call
    console.log("Submission:", { ...formState, estimate });
  };

  return (
    <div className="bg-gray-50 min-h-screen">
      <div className="bg-[#CB4154] text-white py-16">
        <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 text-center">
          <h1 className="text-4xl md:text-6xl font-bold oswald uppercase">Instant Quote Calculator</h1>
          <p className="mt-4 text-xl font-light opacity-90">Fair pricing. Clean work. No hidden surprises.</p>
        </div>
      </div>

      <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 -mt-8 pb-24">
        <div className="grid grid-cols-1 lg:grid-cols-3 gap-8">

          {/* Inputs Section */}
          <div className="lg:col-span-2 space-y-8">
            <div className="bg-white p-8 rounded-lg shadow-xl border-t-4 border-[#CB4154]">
              <h2 className="text-2xl font-bold oswald mb-6 flex items-center gap-2">
