                Project Details
              </h2>

              <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                <div>
                  <label className="block text-sm font-bold text-gray-700 uppercase mb-2">Service Type</label>
                  <select 
                    value={serviceType}
                    onChange={(e) => setServiceType(e.target.value as ServiceType)}
                    className="w-full bg-gray-50 border border-gray-200 rounded-md p-3 focus:ring-2 focus:ring-[#CB4154] outline-none"
                  >
                    <option value={ServiceType.BRICK}>Bricklaying (Standard)</option>
                    <option value={ServiceType.BLOCK}>Blocklaying (Standard)</option>
                    <option value={ServiceType.VENEER}>Brick Veneer</option>
                    <option value={ServiceType.RETAINING}>Block Retaining Wall</option>
                  </select>
                </div>

                <div>
                  <label className="block text-sm font-bold text-gray-700 uppercase mb-2">Area Size (m²)</label>
                  <input 
                    type="number" 
                    placeholder="e.g. 50" 
                    className="w-full bg-gray-50 border border-gray-200 rounded-md p-3 focus:ring-2 focus:ring-[#CB4154] outline-none"
                    value={area === 0 ? '' : area}
                    onChange={(e) => setArea(Number(e.target.value))}
                  />
                </div>

                <div>
                  <label className="block text-sm font-bold text-gray-700 uppercase mb-2">Site Complexity</label>
                  <select 
                    value={complexity}
                    onChange={(e) => setComplexity(Number(e.target.value))}
                    className="w-full bg-gray-50 border border-gray-200 rounded-md p-3 focus:ring-2 focus:ring-[#CB4154] outline-none"
                  >
                    <option value={1.0}>Standard (Flat, Easy Access)</option>
                    <option value={1.2}>Moderate (Sloped, Corners)</option>
                    <option value={1.5}>Complex (High Detail, Bad Access)</option>
                  </select>
                </div>

                <div className="flex items-center gap-3 pt-8">
                  <input 
                    type="checkbox" 
                    id="materials"
                    checked={includeMaterials}
                    onChange={(e) => setIncludeMaterials(e.target.checked)}
                    className="w-5 h-5 accent-[#CB4154]"
                  />
                  <label htmlFor="materials" className="text-sm font-semibold text-gray-700">Include Materials (Brick/Block, Sand, Cement)</label>
                </div>
              </div>
            </div>

            <div className="bg-white p-8 rounded-lg shadow-xl">
              <h2 className="text-2xl font-bold oswald mb-6">Request Callback & Booking</h2>

              {!formState.submitted ? (
