                    <label className="block text-sm font-bold text-gray-700 uppercase mb-2">Full Name</label>
                    <input required type="text" className="w-full bg-gray-50 border border-gray-200 rounded-md p-3 outline-none focus:border-[#CB4154]" value={formState.name} onChange={e => setFormState({...formState, name: e.target.value})} />
                  </div>
                  <div className="col-span-1">
                    <label className="block text-sm font-bold text-gray-700 uppercase mb-2">Email Address</label>
                    <input required type="email" className="w-full bg-gray-50 border border-gray-200 rounded-md p-3 outline-none focus:border-[#CB4154]" value={formState.email} onChange={e => setFormState({...formState, email: e.target.value})} />
                  </div>
                  <div className="col-span-1">
                    <label className="block text-sm font-bold text-gray-700 uppercase mb-2">Phone Number</label>
                    <input required type="tel" className="w-full bg-gray-50 border border-gray-200 rounded-md p-3 outline-none focus:border-[#CB4154]" value={formState.phone} onChange={e => setFormState({...formState, phone: e.target.value})} />
                  </div>
                  <div className="col-span-2">
                    <label className="block text-sm font-bold text-gray-700 uppercase mb-2">Project Notes</label>
                    <textarea rows={4} className="w-full bg-gray-50 border border-gray-200 rounded-md p-3 outline-none focus:border-[#CB4154]" placeholder="Tell us more about the project location and timeframe..." value={formState.notes} onChange={e => setFormState({...formState, notes: e.target.value})}></textarea>
                  </div>
                  <button type="submit" className="col-span-2 bg-gray-900 text-white py-4 font-bold oswald uppercase tracking-wider hover:bg-[#CB4154] transition-colors rounded-sm">
                    SUBMIT QUOTE REQUEST
                  </button>
                </form>
              ) : (
                <div className="text-center py-10 bg-green-50 border border-green-200 rounded-lg">
                  <svg className="w-16 h-16 text-green-500 mx-auto mb-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M5 13l4 4L19 7" /></svg>
                  <h3 className="text-2xl font-bold text-green-800 oswald uppercase">Request Received!</h3>
                  <p className="text-green-700 mt-2">Thanks {formState.name}. I'll review your quote and get in touch shortly.</p>
                </div>
              )}
            </div>
          </div>

          {/* Sticky Summary Card */}
          <div className="lg:col-span-1">
            <div className="bg-white p-8 rounded-lg shadow-2xl border-t-8 border-[#CB4154] sticky top-28">
              <h3 className="text-2xl font-bold oswald mb-6 border-b pb-4 flex items-center gap-2">
                <svg className="w-6 h-6 text-[#CB4154]" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M12 8c-1.657 0-3 .895-3 2s1.343 2 3 2 3 .895 3 2-1.343 2-3 2m0-8c1.11 0 2.08.402 2.599 1M12 8V7m0 1v8m0 0v1m0-1c-1.11 0-2.08-.402-2.599-1M21 12a9 9 0 11-18 0 9 9 0 0118 0z" /></svg>
                Estimated Quote
              </h3>

              <div className="space-y-4 mb-8">
                <div className="flex justify-between text-gray-600">
                  <span>Labor Cost</span>
                  <span className="font-semibold text-gray-900">{formatCurrency(estimate.labor)}</span>
                </div>
                {includeMaterials && (
                  <div className="flex justify-between text-gray-600">
                    <span>Materials</span>
                    <span className="font-semibold text-gray-900">{formatCurrency(estimate.materials)}</span>
                  </div>
                )}
                <div className="flex justify-between text-gray-600 pt-4 border-t">
                  <span>Subtotal (excl. GST)</span>
                  <span className="font-semibold text-gray-900">{formatCurrency(estimate.subtotal)}</span>
                </div>
                <div className="flex justify-between text-gray-600">
                  <span>GST (15%)</span>
                  <span className="font-semibold text-gray-900">{formatCurrency(estimate.gst)}</span>
                </div>
              </div>

              <div className="bg-[#CB4154]/5 p-6 rounded-lg text-center">
                <p className="text-xs font-bold text-[#CB4154] uppercase tracking-widest mb-1">Total Estimate</p>
                <p className="text-4xl font-bold text-[#CB4154] oswald">{formatCurrency(estimate.total)}</p>
              </div>

              <p className="mt-6 text-[10px] text-gray-400 italic leading-tight">
                * This is a professional estimate based on m² rates. Final pricing subject to site inspection. Pricing includes standard pointing to NZS 3604.
              </p>
            </div>
          </div>

        </div>
      </div>

      {/* Service Area Map Mockup */}
      <div className="bg-white py-20 border-t">
        <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 text-center">
          <h2 className="text-3xl font-bold oswald mb-10">OUR SERVICE AREAS</h2>
          <div className="flex flex-wrap justify-center gap-3 mb-10">
            {CONTACT_INFO.areas.map(area => (
              <span key={area} className="bg-gray-100 px-4 py-2 rounded-full text-sm font-semibold text-gray-600 border border-gray-200">{area}</span>
            ))}
          </div>
          <div className="h-96 w-full rounded-2xl overflow-hidden shadow-inner bg-gray-200">
